/**
 * The blog (SPEC 13a `content_blog_posts`, SPEC 13b §2 `GET /v1/content/*` and §8 `/ops/blog*`, SPEC 13e §1.3 "Blog"
 * and §2.3 "Sitemap", gaps G6-G8 and G10).
 *
 * - Ops writes articles (draft → queued or published → unpublished). Publishing refuses off-product text with 422
 *   `off_product` and `fields` naming the parts that use the earlier product's words (off-product.ts). The queue is
 *   published one article a day by the `blog.publish-queued` job.
 * - The site reads published, on-product articles only: `GET /v1/content/blog` (cursor pages), `/blog/{slug}` and
 *   `/sitemap`. Markdown is returned as written; the site and the Ops preview render it with the same sanitizer.
 * - The body is also checked here (`blogBodyProblem`, on create, patch, publish and the public reads): no raw HTML,
 *   links only to https, http, mailto or a relative path, images only from https. A renderer sanitizer stays the second
 *   line, never the only one.
 */
import { z } from "zod";
import type { ApiResult, Client } from "./client";
import { uuidSchema } from "./ids";
import type { TextLimit } from "./limits";
import { isOnProductText } from "./off-product";
import { text } from "./text";

export const BLOG_STATUSES = ["draft", "queued", "published", "unpublished"] as const;
export type BlogStatus = (typeof BLOG_STATUSES)[number];

const L = (min: number, max: number): TextLimit => ({ min, max });
/** SPEC 13e: title 80, SEO title 60, description 155; the rest as the Ops editor uses them. */
export const BLOG_LIMITS = {
  slug: L(3, 80),
  title: L(3, 80),
  seoTitle: L(0, 60),
  description: L(0, 155),
  tag: L(2, 30),
  tags: 8,
  body: L(30, 30_000),
} as const;

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const SLUG_PROBLEM = "Use lower-case letters, digits and single hyphens.";

export const blogSlugSchema = z
  .string({ error: SLUG_PROBLEM })
  .refine((v) => v.length >= BLOG_LIMITS.slug.min, `Use at least ${BLOG_LIMITS.slug.min} characters.`)
  .refine((v) => v.length <= BLOG_LIMITS.slug.max, `Use ${BLOG_LIMITS.slug.max} characters or fewer.`)
  .regex(SLUG, SLUG_PROBLEM);

const optionalText = (limit: TextLimit) =>
  z.preprocess((v) => (typeof v === "string" && v.trim() === "" ? null : v), text({ min: 1, max: limit.max }, { noEmoji: true }).nullable());

const tagsSchema = z
  .array(text(BLOG_LIMITS.tag, { noEmoji: true }), { error: "Add the tags as a list." })
  .max(BLOG_LIMITS.tags, `Use ${BLOG_LIMITS.tags} tags or fewer.`)
  .refine((t) => new Set(t.map((x) => x.toLowerCase())).size === t.length, "Each tag only once.");

/** A raw HTML tag, comment or declaration; Markdown autolinks (`<https://...>`, `<mailto:...>`) are allowed. */
const RAW_HTML = /<(?!(?:https?:\/\/|mailto:)[^\s<>]*>)[!/?a-z]/i;
/** Inline links and images `[t](url` / `![a](url`, and reference definitions `[id]: url`. */
const INLINE_LINK = /(!?)\[[^\]]*\]\(\s*<?([^\s)>]*)/g;
const REF_DEF = /^ {0,3}\[[^\]]+\]:\s*<?([^\s>]+)/gm;
const SCHEME = /^([a-z][a-z0-9+.-]*):/i;

function urlProblem(url: string, image: boolean): string | null {
  // an entity, a control character or a backslash can hide a scheme from this check but not from a renderer
  const hidden = /&(?:#|[a-z]+;)/i.test(url) || url.includes("\\") || [...url].some((ch) => ch.charCodeAt(0) < 32 || ch.charCodeAt(0) === 127);
  if (hidden) return "Write the link address without codes or backslashes.";
  const scheme = SCHEME.exec(url)?.[1]?.toLowerCase();
  if (image) return scheme === "https" ? null : "Images must use an https address.";
  return scheme === undefined || scheme === "https" || scheme === "http" || scheme === "mailto" ? null : "Links may only use https, http, mailto or a path on this site.";
}

/** Why an article body is unsafe to render, or null (G8 and the stored-XSS rule). */
export function blogBodyProblem(body: string): string | null {
  if (RAW_HTML.test(body)) return "Remove the HTML tags. Use Markdown instead.";
  for (const m of body.matchAll(INLINE_LINK)) {
    const problem = urlProblem(m[2] ?? "", m[1] === "!");
    if (problem) return problem;
  }
  for (const m of body.matchAll(REF_DEF)) {
    const problem = urlProblem(m[1] ?? "", false);
    if (problem) return problem;
  }
  return null;
}

const blogFields = {
  slug: blogSlugSchema,
  title: text(BLOG_LIMITS.title, { noEmoji: true }),
  seoTitle: optionalText(BLOG_LIMITS.seoTitle),
  description: optionalText(BLOG_LIMITS.description),
  tags: tagsSchema,
  coverMediaId: uuidSchema.nullable(),
  body: text(BLOG_LIMITS.body, { multiline: true, noEmoji: true }).superRefine((v, ctx) => {
    const problem = blogBodyProblem(v);
    if (problem) ctx.addIssue({ code: "custom", message: problem });
  }),
};

/** `POST /ops/blog` (a new draft). */
export const blogInputSchema = z.strictObject(blogFields);
export type BlogInput = z.output<typeof blogInputSchema>;

/** `PATCH /ops/blog/{id}`: any of the fields, with the version read. */
export const blogPatchSchema = z
  .strictObject({
    slug: blogFields.slug.optional(),
    title: blogFields.title.optional(),
    seoTitle: blogFields.seoTitle.optional(),
    description: blogFields.description.optional(),
    tags: blogFields.tags.optional(),
    coverMediaId: blogFields.coverMediaId.optional(),
    body: blogFields.body.optional(),
    version: z.number({ error: "Reload the article and try again." }).int().min(1),
  });
export type BlogPatch = z.output<typeof blogPatchSchema>;

/** `POST /ops/blog/queue { ids }`: the whole queue in order; `[]` clears it (the posts go back to drafts). */
export const blogQueueSchema = z.strictObject({
  ids: z
    .array(uuidSchema)
    .max(100, "Queue 100 articles or fewer.")
    .refine((ids) => new Set(ids).size === ids.length, "Each article only once."),
});
export type BlogQueueBody = z.output<typeof blogQueueSchema>;

/** A row of the Ops list. */
export interface BlogRow {
  id: string;
  slug: string;
  title: string;
  status: BlogStatus;
  queuePosition: number | null;
  publishedAt: string | null;
  updatedAt: string;
}

/** `GET /ops/blog/{id}` and every write's answer. `onProduct` mirrors the publish rule (G8). */
export interface BlogPost extends BlogRow {
  seoTitle: string | null;
  description: string | null;
  tags: string[];
  coverMediaId: string | null;
  coverUrl: string | null;
  body: string;
  version: number;
  onProduct: boolean;
  createdAt: string;
}

/** The fields a publish checks, and the field each one is reported on. */
export function offProductFields(p: { title: string; description: string | null; seoTitle: string | null; tags: string[]; body: string }): Record<string, string> {
  const msg = "Remove the words Phriend no longer uses.";
  const out: Record<string, string> = {};
  if (!isOnProductText(p.title)) out.title = msg;
  if (p.seoTitle && !isOnProductText(p.seoTitle)) out.seoTitle = msg;
  if (p.description && !isOnProductText(p.description)) out.description = msg;
  if (!isOnProductText(p.tags.join(" "))) out.tags = msg;
  if (!isOnProductText(p.body)) out.body = msg;
  return out;
}

